// Domain 3 — Content inspection flashcards.
export default [
  // 3.1 SSL/SSH inspection and certificates
  { id: 'd3-f001', topic: '3.1', front: 'Certificate inspection reads what?', back: 'Only the TLS handshake: the SNI in the Client Hello and, when visible, the server certificate. No payload, so no AV, path-level URL filter or DLP on HTTPS.' },
  { id: 'd3-f002', topic: '3.1', front: 'Which built-in SSL/SSH inspection profile can be edited?', back: '`custom-deep-inspection`. `certificate-inspection`, `deep-inspection` and `no-inspection` are read-only, so clone or create a profile to customise.' },
  { id: 'd3-f003', topic: '3.1', front: 'Default `caname` and `untrusted-caname` in an SSL/SSH inspection profile?', back: '`Fortinet_CA_SSL` (re-signs trusted sites) and `Fortinet_CA_Untrusted` (re-signs sites whose real certificate failed validation, so users still see a warning).' },
  { id: 'd3-f004', topic: '3.1', front: 'Should Fortinet_CA_Untrusted be installed on endpoints?', back: 'Never. It exists to keep the browser warning for bad server certificates. Install Fortinet_CA_SSL or an enterprise sub-CA instead.' },
  { id: 'd3-f005', topic: '3.1', front: '`server-cert-mode re-sign` vs `replace`?', back: '`re-sign` (default): FortiGate generates a copy of the server certificate signed by its CA, used for outbound traffic. `replace`: present your own uploaded server certificate, used for Protecting SSL Server (inbound).' },
  { id: 'd3-f006', topic: '3.1', front: 'Default FortiGuard categories exempted from deep inspection?', back: 'Finance and Banking (31), Health and Wellness (33) and Personal Privacy (87).' },
  { id: 'd3-f007', topic: '3.1', front: 'GUI "Keep Untrusted & Allow" vs "Trust & Allow"?', back: 'CLI `allow` vs `ignore`. Keep Untrusted re-signs with Fortinet_CA_Untrusted (warning kept). Trust & Allow re-signs with the trusted CA (warning hidden).' },
  { id: 'd3-f008', topic: '3.1', front: 'Default actions: expired, revoked, untrusted server certificate?', back: 'Expired: block. Revoked: block. Untrusted: allow (as untrusted). Validation timeout: allow. Validation failure: block.' },
  { id: 'd3-f009', topic: '3.1', front: '`sni-server-cert-check` options?', back: '`enable` (default): on an SNI/CN mismatch, use the certificate CN for URL filtering. `strict`: close the connection. `disable`: no check.' },
  { id: 'd3-f010', topic: '3.1', front: 'Why does deep inspection break mutual-TLS sites, and what is the default?', back: 'FortiGate cannot present the user\'s client certificate (no private key). HTTPS `client-certificate` defaults to `bypass`.' },
  { id: 'd3-f011', topic: '3.1', front: 'What does TLS 1.3 hide from certificate inspection, and what can FortiGate do?', back: 'The server certificate (encrypted after Server Hello). FortiGate relies on SNI and can probe the server for its certificate. `cert-probe-failure` (default allow) decides what happens if the probe fails.' },
  { id: 'd3-f012', topic: '3.1', front: 'Default for `encrypted-client-hello` in the HTTPS table?', back: '`block`. Blocking ECH makes the browser fall back to a normal Client Hello, so the SNI is visible to certificate inspection. DNS filter `strip-ech` can also remove ECH keys.' },
  { id: 'd3-f013', topic: '3.1', front: '8.0 hybrid PQC group typically negotiated through proxy-mode deep inspection?', back: '`X25519MLKEM768` (also SecP256r1MLKEM768, SecP384r1MLKEM1024 and pure ML-KEM). 8.0.1 `tls-handshake-mode dual` negotiates each leg independently.' },
  { id: 'd3-f014', topic: '3.1', front: 'What is the 8.0 feature "TLS 1.3 based VPN over TCP"?', back: 'IKE/ESP over TCP wrapped in TLS 1.3 (`set ike-tcp-service enable`, `set ike-tls-service enable` per VDOM). FortiGate-to-FortiGate only; IKE still negotiates the keys; the gateway list shows `transport: TLS`.' },

  // 3.2 Inspection modes and web filtering
  { id: 'd3-f015', topic: '3.2', front: 'Default inspection mode of a new firewall policy?', back: 'Flow-based (`set inspection-mode flow`).' },
  { id: 'd3-f016', topic: '3.2', front: 'Which daemons do flow and proxy inspection?', back: 'Flow: the IPS engine (`ipsengine`). Proxy: WAD and the other proxy daemons, with `scanunit` for AV scanning.' },
  { id: 'd3-f017', topic: '3.2', front: 'Proxy-only security profiles in 8.0?', back: 'Video filter, inline CASB, ICAP, WAF, SSH filter and WebSocket inspection.' },
  { id: 'd3-f018', topic: '3.2', front: 'Flow-mode AV detects malware on an HTTP download after part of it was forwarded. What does the user see?', back: 'The session is reset (broken download). The IPS engine caches the URL, and the replacement message is shown on the next attempt.' },
  { id: 'd3-f019', topic: '3.2', front: 'Web filter order of operations?', back: 'Static URL filter → FortiGuard category filter → web content filter → web script filter → antivirus.' },
  { id: 'd3-f020', topic: '3.2', front: 'URL filter `allow` vs `exempt`?', back: '`allow` only means not blocked by the URL filter; FortiGuard and other checks still run. `exempt` skips the remaining inspection (narrow it with `set exempt`).' },
  { id: 'd3-f021', topic: '3.2', front: 'FortiGuard category actions?', back: 'Allow, Monitor, Block, Warning, Authenticate. Disable exists for local/remote categories only.' },
  { id: 'd3-f022', topic: '3.2', front: 'Category precedence when a URL is in several categories?', back: 'Local category → remote (external feed) category → FortiGuard category.' },
  { id: 'd3-f023', topic: '3.2', front: 'CLI option for "Allow websites when a rating error occurs"?', back: '`set options error-allow` under `config ftgd-wf`. Without it (the default), rating errors block the site.' },
  { id: 'd3-f024', topic: '3.2', front: 'Why does safe search have no effect with certificate inspection?', back: 'Safe search rewrites the HTTPS request (URL/header), which requires deep inspection. Certificate inspection cannot modify encrypted requests.' },
  { id: 'd3-f025', topic: '3.2', front: 'Flow-mode limits on local/remote web filter categories?', back: 'They do not support the warning and authenticate actions and cannot be overridden.' },
  { id: 'd3-f026', topic: '3.2', front: 'FortiGuard web filter category for GenAI sites?', back: 'Category 100, Artificial Intelligence Technology (group General Interest – Business).' },
  { id: 'd3-f027', topic: '3.2', front: 'Requirements for DLP blocking of GenAI chatbot prompts?', back: 'Proxy-mode policy, deep inspection, DLP profile (`feature-set proxy`) with `proto http-post` rules (`type message` for prompts, file type for uploads), and application control blocking QUIC.' },
  { id: 'd3-f028', topic: '3.2', front: 'Command that shows FortiGuard rating server reachability, licence status and the server list?', back: '`diagnose debug rating`' },

  // 3.3 Application control
  { id: 'd3-f029', topic: '3.3', front: 'Which engine performs application control?', back: 'The IPS engine, in both flow and proxy policies, using FortiGuard application signatures and protocol decoders.' },
  { id: 'd3-f030', topic: '3.3', front: 'GUI Monitor vs Allow in application control?', back: 'Both are CLI `action pass`. Monitor logs (`log enable`); Allow does not.' },
  { id: 'd3-f031', topic: '3.3', front: 'Are overrides or categories evaluated first?', back: 'Application and filter overrides, top-down, before the category settings (the default segment).' },
  { id: 'd3-f032', topic: '3.3', front: 'Facebook (weight 10) and SSL (weight 1) both match in the same segment. Which wins?', back: 'Facebook. Higher application weight wins; specific apps outweigh generic protocols.' },
  { id: 'd3-f033', topic: '3.3', front: '`enforce-default-app-port enable` does what?', back: 'Blocks monitored or allowed applications detected on non-default ports. Blocked apps stay blocked on any port.' },
  { id: 'd3-f034', topic: '3.3', front: 'Default `other-application-action` and `unknown-application-action`?', back: 'Both `pass`, and their logging (`other-application-log`, `unknown-application-log`) is disabled by default.' },
  { id: 'd3-f035', topic: '3.3', front: 'Application control category ID for Generative AI?', back: '`36` (GenAI). Signatures come from the GenAI Application Definitions (AIAP) database.' },
  { id: 'd3-f036', topic: '3.3', front: 'Extra log fields from GenAI app control with `extended-log enable` and deep inspection?', back: '`aiuser`, `model`, `dcgeo`, `usecase`, `prompt`, `cloudgenai`.' },
  { id: 'd3-f037', topic: '3.3', front: 'How is application control applied in policy-based NGFW mode?', back: 'Applications and categories are set directly in `config firewall security-policy` (no sensor). Flow inspection only.' },
  { id: 'd3-f038', topic: '3.3', front: 'Why does a blocked application still show some bytes in the traffic log?', back: 'The handshake and first data packets must pass before a signature can identify the application.' },
  { id: 'd3-f039', topic: '3.3', front: 'Why block the QUIC application in many sensors?', back: 'Browsers then fall back from UDP/443 QUIC to TCP/TLS, where deep inspection, web filter and DLP apply fully.' },

  // 3.4 Antivirus
  { id: 'd3-f040', topic: '3.4', front: 'AV database tiers and the default?', back: 'Normal (base), extended (default: current plus recent malware) and extreme (adds dormant "zoo" malware; `use-extreme-db enable` on supported models).' },
  { id: 'd3-f041', topic: '3.4', front: 'Lowest hardware model supporting the extreme AV database (8.0 guide)?', back: 'FortiGate 121G. All FortiGate VMs support it.' },
  { id: 'd3-f042', topic: '3.4', front: 'Proxy-only antivirus features?', back: 'Content disarm and reconstruction, client comforting, FortiNDR inline detection, and scanning of MAPI and SSH (SCP/SFTP).' },
  { id: 'd3-f043', topic: '3.4', front: 'Flow-mode AV "default scan" vs "full scan"?', back: 'Default: stream-based scanning in the IPS engine (HTML/JS) and the flow DB. Full: the whole file is cached and sent to scanunit, triggered by ML, extreme DB, grayware, outbreak prevention, DLP and similar features.' },
  { id: 'd3-f044', topic: '3.4', front: 'Proxy AV `scan-mode` options?', back: '`default` (stream-based, in-process where possible) and `legacy` (stream-based scanning disabled, for troubleshooting).' },
  { id: 'd3-f045', topic: '3.4', front: 'Default HTTP `oversize-limit` and the default handling of oversized files?', back: '10 MB. Oversized files are passed unscanned unless `options oversize` is set (which blocks them).' },
  { id: 'd3-f046', topic: '3.4', front: 'Client comforting defaults?', back: '`comfort-interval 10` seconds, `comfort-amount 1` byte. Proxy mode only, enabled with `options clientcomfort`.' },
  { id: 'd3-f047', topic: '3.4', front: 'Log ID, subtype and eventtype of an AV infection log?', back: '`logid="0211008192"`, `subtype="virus"`, `eventtype="infected"`. Filter with `execute log filter category 2`.' },
  { id: 'd3-f048', topic: '3.4', front: 'Password-protected ZIP passes antivirus. Which setting blocks it?', back: '`archive-block encrypted` in the protocol table of the antivirus profile.' },
  { id: 'd3-f049', topic: '3.4', front: 'Default `av-failopen` and its meaning?', back: '`pass`: in memory conserve mode, proxy-based traffic bypasses the AV proxy unscanned. `off` blocks new sessions needing it; `one-shot` keeps bypassing after conserve mode ends. Flow mode follows IPS `fail-open`.' },
  { id: 'd3-f050', topic: '3.4', front: 'Where are ports for cleartext protocols vs TLS protocols mapped?', back: 'Cleartext (HTTP 80, SMTP, FTP 21…): protocol options profile. HTTPS/SMTPS/IMAPS/POP3S/FTPS: SSL/SSH inspection profile (proxy policies).' },

  // 3.5 IPS
  { id: 'd3-f051', topic: '3.5', front: 'IPS sensor entry types?', back: 'Signature entries (specific rule IDs) and filter entries (severity, location, protocol, OS, application, CVE…). A filter must match all selected attributes.' },
  { id: 'd3-f052', topic: '3.5', front: 'IPS entry `action` options in CLI?', back: '`pass`, `block`, `reset`, `default` (each signature\'s own default action). The GUI also offers Monitor and Quarantine.' },
  { id: 'd3-f053', topic: '3.5', front: 'What does `status enable` on a filter entry do?', back: 'Enables every matching signature, including those disabled by default. `status default` keeps each signature\'s default status.' },
  { id: 'd3-f054', topic: '3.5', front: 'IPS signature used for AI/ML DNS tunnelling detection in 8.0?', back: '`DNS.Tunnelling`, rule 58322. Severity low, default action pass, so add it with `action block`. No deep inspection needed.' },
  { id: 'd3-f055', topic: '3.5', front: 'Global setting and package required for AI/ML IPS detection?', back: '`config ips global` → `set machine-learning-detection enable` (default) plus the AI/Machine Learning IPS Definitions package (IPS subscription).' },
  { id: 'd3-f056', topic: '3.5', front: 'What is the "FortiGuard Extended SaaS DB"?', back: 'Best match in the 8.0 docs: the Expanded CASB SaaS application database (2,700+ SaaS apps, Inline-CASB → SaaS Application, FMWR licence). Inline CASB is proxy-only.' },
  { id: 'd3-f057', topic: '3.5', front: '`config ips global` `fail-open` default and meaning?', back: '`disable`: when the IPS socket buffer is full (or in conserve mode), sessions needing IPS are dropped. `enable`: traffic passes uninspected. NTurbo sessions cannot fail open.' },
  { id: 'd3-f058', topic: '3.5', front: 'ipsmonitor option to put the IPS engine in bypass for a CPU test?', back: '`diagnose test application ipsmonitor 5` toggles bypass. The engine runs but stops inspecting.' },
  { id: 'd3-f059', topic: '3.5', front: 'Why might a new FortiGate show stale IPS definitions despite a valid licence?', back: 'IPS packages are only downloaded when at least one firewall policy uses an IPS sensor.' },
  { id: 'd3-f060', topic: '3.5', front: 'IPS signature log ID and CLI log filter category?', back: '`logid="0419016384"`, `subtype="ips"`. Use `execute log filter category 4`.' },
];
